def node(nid,title,kind,summary,sids,tags=[]):
    i=int(hashlib.sha256(nid.encode()).hexdigest()[:6],16)
    r=node_record(nid,title,kind,summary,sids,round(0.55+0.2*math.cos(i*2.4),6),round(0.45+0.2*math.sin(i*2.4),6),tags)
    r.update(connection_pass=MARK,status='candidate',review_status='research_pass_needs_editor',reviewed_by='',reviewed_at='',inclusion_reason=MARK,set_tags=enc(['systems','release_0_30',*tags]))
    upsert(d['nodes'],[r],'id');return nid
def edge(eid,a,b,typ,sid,locator,scope):
    family=next(r['relation_family'] for r in d['relation_types'] if r['relation_type']==typ)
    r=edge_record(eid,a,b,typ,family,typ.replace('_',' '),[sid],locator,scope,status='candidate',confidence='',review_label='Located source statement; curator review pending')
    vid='ev_'+eid;cid='claim_'+eid;r.update(connection_pass=MARK,evidence_ids=enc([vid]),claim_id=cid)
    upsert(d['edges'],[r],'id')
    upsert(d['evidence'],[dict(id=vid,source_id=sid,locator=locator,excerpt_or_summary=scope,evidence_type='located_public_source',quality_tier='B',licence='source terms',review_status='research_pass_needs_editor',content_hash='',public_evidence_status='public',connection_pass=MARK)],'id')
    upsert(d['claims'],[dict(id=cid,statement=scope,subject_id=a,predicate=typ,object_id=b,status='candidate',supporting_source_ids=enc([sid]),supporting_evidence_ids=enc([vid]),contradicting_source_ids='[]',contradicting_evidence_ids='[]',notes='Scope is limited to the identified source passage.',review_status='research_pass_needs_editor',reviewed_by='',reviewed_at='',connection_pass=MARK)],'id')
